// Merge updates into original rows; keep header order exactly
try {
  const originalItems = $items('Read Excel File', 0) || [];
  const inputItems = $input.all();
  const updates = (inputItems[0] && inputItems[0].json && inputItems[0].json.updates) ? inputItems[0].json.updates : [];
  if (!originalItems.length) {
    return [{ json: { error: 'Нет данных из узла Read Excel File' } }];
  }

  // Build lookup by ticket
  const byTicket = new Map();
  for (const u of updates) {
    const t = String(u['№ Тикета'] ?? '').trim();
    if (!t) continue;
    const data = {
      timeProcessing: u['Время обработки'] || '',
      timeTaking: u['Время с момента передачи тикета до взятия его обратно в работу сотрудниками ЦКП'] || ''
    };
    byTicket.set(t, data);
    if (!isNaN(Number(t))) byTicket.set(String(Number(t)), data);
  }

  function findKeyByPrefix(keys, prefix) {
    for (const k of keys) {
      const s = String(k ?? '').trim();
      if (s && s.startsWith(prefix)) return k;
    }
    return null;
  }

  const headerKeys = Object.keys(originalItems[0].json || {});
  const ticketKey = '№ Тикета';
  if (!headerKeys.includes(ticketKey)) {
    return [{ json: { error: 'Столбец "№ Тикета" не найден', headerKeys } }];
  }
  const timeProcessingKey = findKeyByPrefix(headerKeys, 'Время обработки') || 'Время обработки (D2-B2)';
  const timeTakingKey = findKeyByPrefix(headerKeys, 'Время с момента передачи тикета до взятия его обратно в работу сотрудниками ЦКП') || 'Время с момента передачи тикета до взятия его обратно в работу сотрудниками ЦКП (G2-B2)';

  // Ensure both keys exist in header; if missing, append to keep consistent order
  const finalHeader = headerKeys.slice();
  if (!finalHeader.includes(timeProcessingKey)) finalHeader.push(timeProcessingKey);
  if (!finalHeader.includes(timeTakingKey)) finalHeader.push(timeTakingKey);

  // Функция для парсинга времени из формата \"Xч Xм\" в минуты
  function parseTimeToMinutes(timeStr) {
    if (!timeStr || typeof timeStr !== 'string') return null;
    const match = timeStr.match(/(\d+)ч\s*(\d+)м/);
    if (!match) return null;
    const hours = parseInt(match[1], 10);
    const minutes = parseInt(match[2], 10);
    return hours * 60 + minutes;
  }

  // Функция для форматирования минут в \"Xч Xм\"
  function formatMinutesToTime(totalMinutes) {
    if (totalMinutes === null || isNaN(totalMinutes)) return '';
    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;
    return hours + 'ч ' + minutes + 'м';
  }

  const records = [];
  const timeProcessingValues = [];
  const timeTakingValues = [];

  for (const it of originalItems) {
    const src = it.json || {};
    const ticketVal = String(src[ticketKey] ?? '').trim();
    const ticketNum = isNaN(Number(ticketVal)) ? null : String(Number(ticketVal));
    let upd = null;
    if (byTicket.has(ticketVal)) upd = byTicket.get(ticketVal);
    else if (ticketNum && byTicket.has(ticketNum)) upd = byTicket.get(ticketNum);

    // Build ordered object following finalHeader
    const out = {};
    for (const key of finalHeader) {
      if (key === timeProcessingKey) {
        const value = upd ? upd.timeProcessing : (key in src ? src[key] : '');
        out[key] = value;
        const minutes = parseTimeToMinutes(value);
        if (minutes !== null) timeProcessingValues.push(minutes);
      } else if (key === timeTakingKey) {
        const value = upd ? upd.timeTaking : (key in src ? src[key] : '');
        out[key] = value;
        const minutes = parseTimeToMinutes(value);
        if (minutes !== null) timeTakingValues.push(minutes);
      } else {
        out[key] = key in src ? src[key] : '';
      }
    }
    records.push(out);
  }

  // Вычисляем средние значения
  const avgTimeProcessing = timeProcessingValues.length > 0
    ? timeProcessingValues.reduce((a, b) => a + b, 0) / timeProcessingValues.length
    : null;
  const avgTimeTaking = timeTakingValues.length > 0
    ? timeTakingValues.reduce((a, b) => a + b, 0) / timeTakingValues.length
    : null;

  // Добавляем строку со средним значением
  const avgRow = {};
  for (const key of finalHeader) {
    if (key === timeProcessingKey) {
      avgRow[key] = formatMinutesToTime(Math.round(avgTimeProcessing));
    } else if (key === timeTakingKey) {
      avgRow[key] = formatMinutesToTime(Math.round(avgTimeTaking));
    } else if (key === ticketKey) {
      avgRow[key] = 'Среднее';
    } else {
      avgRow[key] = '';
    }
  }
  records.push(avgRow);

  // Return as array of items for Spreadsheet File (Write)
  return records.map(r => ({ json: r }));
} catch (e) {
  return [{ json: { error: String(e && e.message ? e.message : e) } }];
}

// Сохраняем бинарные данные файла для последующего обновления
const items = $input.all();

// Получаем бинарные данные из первого элемента
const firstItem = items[0];
const binaryData = firstItem.binary?.data || $binary?.data;

// Добавляем бинарные данные к каждому элементу
return items.map(item => {
  const result = { json: item.json };
  if (binaryData) {
    result.binary = { data: binaryData };
  }
  return result;
});

// Функция для преобразования Excel даты (серийный номер) в нормальную дату
function excelDateToJSDate(excelDate) {
  // Excel считает от 1 января 1900, но ошибочно считает 1900 високосным
  // Поэтому нужно вычесть 1 день для дат после 28 февраля 1900
  const excelEpoch = new Date(1899, 11, 30); // 30 декабря 1899
  const days = Math.floor(excelDate);
  const date = new Date(excelEpoch);
  date.setDate(date.getDate() + days);

  // Исправление бага Excel (1900 считается високосным)
  if (days > 59) {
    date.setDate(date.getDate() - 1);
  }

  return date;
}

// Функция для преобразования Excel времени (доля дня) в строку времени
function excelTimeToTimeString(excelTime) {
  // Excel время - это доля дня (0.5 = полдень, 0.25 = 6:00)
  const totalSeconds = Math.floor(excelTime * 24 * 60 * 60);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`.substring(0, 5);
}

// Функция для расчета разницы времени
function calculateTimeDifference(date1, time1, date2, time2) {
  // Нормализуем формат даты
  function normalizeDate(dateValue) {
    if (!dateValue && dateValue !== 0) return null;

    // Если это число (Excel серийный номер даты)
    if (typeof dateValue === 'number') {
      const jsDate = excelDateToJSDate(dateValue);
      const year = jsDate.getFullYear();
      const month = String(jsDate.getMonth() + 1).padStart(2, '0');
      const day = String(jsDate.getDate()).padStart(2, '0');
      return `${year}-${month}-${day}`;
    }

    // Если это объект Date
    if (dateValue instanceof Date) {
      const year = dateValue.getFullYear();
      const month = String(dateValue.getMonth() + 1).padStart(2, '0');
      const day = String(dateValue.getDate()).padStart(2, '0');
      return `${year}-${month}-${day}`;
    }

    // Преобразуем в строку
    const dateString = String(dateValue).trim();
    if (!dateString) return null;

    // Если дата в формате ДД.ММ.ГГГГ, преобразуем в ГГГГ-ММ-ДД
    if (dateString.includes('.')) {
      const parts = dateString.split('.');
      if (parts.length === 3) {
        return `${parts[2]}-${parts[1]}-${parts[0]}`;
      }
    }

    return dateString;
  }

  // Нормализуем формат времени
  function normalizeTime(timeValue) {
    if (!timeValue && timeValue !== 0) return null;

    // Если это число (Excel время как доля дня)
    if (typeof timeValue === 'number') {
      // Если число больше 1, это может быть серийный номер с временем
      if (timeValue >= 1) {
        // Извлекаем только дробную часть (время)
        const timePart = timeValue - Math.floor(timeValue);
        return excelTimeToTimeString(timePart);
      } else {
        // Это чистое время (доля дня)
        return excelTimeToTimeString(timeValue);
      }
    }

    // Если это объект Date, извлекаем время
    if (timeValue instanceof Date) {
      const hours = String(timeValue.getHours()).padStart(2, '0');
      const minutes = String(timeValue.getMinutes()).padStart(2, '0');
      return `${hours}:${minutes}`;
    }

    // Преобразуем в строку
    const timeString = String(timeValue).trim();
    if (!timeString) return null;

    // Убираем секунды, если есть
    return timeString.length > 5 ? timeString.substring(0, 5) : timeString;
  }

  const normalizedDate1 = normalizeDate(date1);
  const normalizedDate2 = normalizeDate(date2);
  const normalizedTime1 = normalizeTime(time1);
  const normalizedTime2 = normalizeTime(time2);

  if (!normalizedDate1 || !normalizedDate2 || !normalizedTime1 || !normalizedTime2) {
    return 'Ошибка: неверный формат даты/времени';
  }

  // Формируем полные даты
  const datetime1 = new Date(`${normalizedDate1} ${normalizedTime1}`);
  const datetime2 = new Date(`${normalizedDate2} ${normalizedTime2}`);

  if (isNaN(datetime1.getTime()) || isNaN(datetime2.getTime())) {
    return 'Ошибка: неверный формат даты/времени';
  }

  // Вычисляем разницу в миллисекундах
  const diff = Math.abs(datetime2 - datetime1);

  // Конвертируем в часы и минуты
  const totalMinutes = Math.floor(diff / (1000 * 60));
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;

  return hours + 'ч ' + minutes + 'м';
}

// Обрабатываем все элементы
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Первый расчет: Время передачи + Дата передачи -> Время возврата + Дата возврата
  let result1 = '';
  if (data['Дата передачи'] && data['Время передачи'] && 
      data['Дата возврата'] && data['Время возврата']) {
    try {
      result1 = calculateTimeDifference(
        data['Дата передачи'],
        data['Время передачи'],
        data['Дата возврата'],
        data['Время возврата']
      );
    } catch (error) {
      result1 = `Ошибка: ${error.message}`;
    }
  }

  // Второй расчет: Время передачи + Дата передачи -> Время взятия тикета + Дата взятия тикета
  let result2 = '';
  if (data['Дата передачи'] && data['Время передачи'] && 
      data['Дата взятия тикета в работу сотрудником ЦКП'] && 
      data['Время взятия тикета в работу сотрудником ЦКП']) {
    try {
      result2 = calculateTimeDifference(
        data['Дата передачи'],
        data['Время передачи'],
        data['Дата взятия тикета в работу сотрудником ЦКП'],
        data['Время взятия тикета в работу сотрудником ЦКП']
      );
    } catch (error) {
      result2 = `Ошибка: ${error.message}`;
    }
  }

  // Сохраняем бинарные данные, если есть
  const result = {
    json: {
      ...data,
      'Время обработки': result1,
      'Время с момента передачи тикета до взятия его обратно в работу сотрудниками ЦКП': result2
    }
  };

  if (item.binary) {
    result.binary = item.binary;
  }

  results.push(result);
}

return results;

// Подготавливаем данные для обновления Excel файла
const items = $input.all();

// Извлекаем только нужные данные для обновления
const updates = items.map(item => ({
  '№ Тикета': item.json['№ Тикета'],
  'Время обработки': item.json['Время обработки'] || '',
  'Время с момента передачи тикета до взятия его обратно в работу сотрудниками ЦКП': item.json['Время с момента передачи тикета до взятия его обратно в работу сотрудниками ЦКП'] || ''
}));

// Кодируем JSON в base64 для безопасной передачи через аргументы
const updatesJson = JSON.stringify(updates);
const base64Updates = Buffer.from(updatesJson).toString('base64');

// Отладочная информация
console.log('=== DEBUG: Prepare Updates ===');
console.log('Updates count:', updates.length);
console.log('Updates sample:', JSON.stringify(updates.slice(0, 2)));
console.log('Base64 length:', base64Updates.length);
console.log('Base64 preview:', base64Updates.substring(0, 100) + '...');

// Возвращаем один элемент с данными для обновления
return {
  json: {
    base64Updates: base64Updates,
    updatesCount: updates.length,
    updates: updates, // ВСЕ обновления, не только первые 3
    success: true
  }
};
